const LANG=(document.documentElement.lang||'es').slice(0,2);const TXT={es:{wa:'Hola, he visto vuestra web y me gustaría información sobre un viaje a Marruecos.',waLabel:'Escríbenos por WhatsApp',name:'Nombre',email:'Email',type:'Tipo',route:'Ruta',unspec:'Sin especificar',tbd:'Por definir',subj:'Consulta web · ',mail:'Se ha abierto tu programa de correo con la consulta preparada. Pulsa enviar allí.',sending:'Enviando…',ok:'Gracias. Hemos recibido tu consulta y te responderemos en 24–48 horas.',fail:'No hemos podido enviar el formulario. Escríbenos directamente a '},en:{wa:'Hello, I have seen your website and would like information about a trip to Morocco.',waLabel:'Message us on WhatsApp',name:'Name',email:'Email',type:'Type',route:'Route',unspec:'Not specified',tbd:'To be decided',subj:'Website enquiry · ',mail:'Your email app has opened with your enquiry ready. Press send there.',sending:'Sending…',ok:'Thank you. We have received your enquiry and will reply within 24–48 hours.',fail:'We could not send the form. Please write to us directly at '},fr:{wa:'Bonjour, j\u2019ai vu votre site et j\u2019aimerais des informations sur un voyage au Maroc.',waLabel:'Écrivez-nous sur WhatsApp',name:'Nom',email:'E-mail',type:'Type',route:'Itinéraire',unspec:'Non précisé',tbd:'À définir',subj:'Demande via le site · ',mail:'Votre application de messagerie s\u2019est ouverte avec votre demande prête. Appuyez sur envoyer.',sending:'Envoi…',ok:'Merci. Nous avons bien reçu votre demande et nous vous répondrons sous 24 à 48 heures.',fail:'Nous n\u2019avons pas pu envoyer le formulaire. Écrivez-nous directement à '}};const T=TXT[LANG]||TXT.es;
document.addEventListener('DOMContentLoaded',()=>{const header=document.querySelector('.home-page .header, .route-page .header');if(header){const reveal=()=>header.classList.toggle('is-visible',window.scrollY>90);reveal();window.addEventListener('scroll',reveal,{passive:true})}const btn=document.querySelector('.toggle'),links=document.querySelector('.links');if(btn&&links){btn.addEventListener('click',()=>{const open=links.classList.toggle('open');btn.setAttribute('aria-expanded',String(open));btn.textContent=open?'×':'☰'});links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{links.classList.remove('open');btn.setAttribute('aria-expanded','false');btn.textContent='☰'}))}const params=new URLSearchParams(location.search);const type=document.querySelector('#type');if(type&&params.get('tipo'))type.value=params.get('tipo');const route=document.querySelector('#route');if(route&&params.get('ruta')){const wanted=params.get('ruta');for(const opt of route.options){if(opt.text.toLowerCase()===wanted.toLowerCase()){route.value=opt.value;break}}}const form=document.querySelector('#inquiry-form');if(form)form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);if(d.get('_gotcha'))return;const status=document.querySelector('#form-status');const btn=form.querySelector('button[type=submit]');const endpoint=form.dataset.endpoint||'';const to=form.dataset.email;const text=`${T.name}: ${d.get('name')}\n${T.email}: ${d.get('email')}\n${T.type}: ${d.get('type')||T.unspec}\n${T.route}: ${d.get('route')||T.tbd}\n\n${d.get('message')}`;const mailto=()=>{location.href='mailto:'+to+'?subject='+encodeURIComponent(T.subj+(d.get('route')||'Sahara Bless Travel'))+'&body='+encodeURIComponent(text);status.textContent=T.mail};if(!endpoint||endpoint.includes('PEGA_AQUI')){mailto();return}btn.disabled=true;status.textContent=T.sending;try{const r=await fetch(endpoint,{method:'POST',headers:{Accept:'application/json'},body:d});if(!r.ok)throw new Error('HTTP '+r.status);form.reset();status.textContent=T.ok}catch{status.textContent=T.fail+to+'.'}finally{btn.disabled=false}})});
